param([string]$AppExe="",[int]$WarmupSeconds=8,[int]$MeasureSeconds=30,[ValidateSet("idle_shell","certified_core","orb_balanced","orb_eco")][string]$Scenario="idle_shell",[string]$Python="python",[string]$OutDir="")
$ErrorActionPreference='Stop';$Root=Split-Path -Parent $PSScriptRoot;if(-not$OutDir){$OutDir=Join-Path $Root 'build\desktop-benchmark'};New-Item -ItemType Directory -Force $OutDir|Out-Null;if(-not$AppExe){$AppExe=@((Join-Path $Root 'src-tauri\target\release\metatron.exe'),(Join-Path $Root 'src-tauri\target\release\Metatron.exe'))|?{Test-Path $_}|select -First 1};if(-not$AppExe){throw'Built Metatron executable not found'};$before=Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory;$p=Start-Process $AppExe -PassThru;try{Start-Sleep $WarmupSeconds;if($p.HasExited){throw"Metatron exited: $($p.ExitCode)"};$metrics=Join-Path $OutDir 'desktop-metrics.json';& $PSScriptRoot\Collect-WindowsMetrics.ps1 -RootPid $p.Id -DurationSeconds $MeasureSeconds -OutFile $metrics;$after=Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory;@{schema=2;scenario=$Scenario;app_exe=$AppExe;root_pid=$p.Id;available_mib_before=[double]$before.AvailableMBytes;available_mib_after=[double]$after.AvailableMBytes;committed_mib_before=[math]::Round([double]$before.CommittedBytes/1MB,2);committed_mib_after=[math]::Round([double]$after.CommittedBytes/1MB,2)}|ConvertTo-Json|Set-Content -Encoding UTF8 (Join-Path $OutDir 'desktop-summary.json');& $Python $PSScriptRoot\Analyze-WindowsQualification.py $metrics --scenario $Scenario --desktop-summary (Join-Path $OutDir 'desktop-summary.json') --json-out (Join-Path $OutDir 'qualification.json');if($LASTEXITCODE-ne0){throw'Qualification gates failed'}}finally{try{$p.CloseMainWindow()|Out-Null;Start-Sleep 2}catch{};if(-not$p.HasExited){Stop-Process $p.Id -Force -ErrorAction SilentlyContinue}}}
